{
  "title": "A Ubud Day With a Hidden Temple",
  "summary": "A gentle Ubud day that keeps the monkey forest and market, then slips in a lotus temple the crew would not expect.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "Rise and shine, the monkeys are already awake and they do not care about your coffee.",
      "must_do_id_note": null
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "A slower browse after the forest, with plenty of shade and a little local life."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "The surprise: a lotus pond temple tucked behind the main street. I know a guy who swears it is the quietest corner in Ubud."
    }
  ]
}
